import Circuit from "@/app/components/Circuit";

export default function CircuitPage() {
  return (
    <main style={container}>
      
      {/* HERO */}
      <section style={{ marginBottom: "40px" }}>
        <h1 style={title}>
          Interactive Circuit Simulation
        </h1>

        <p style={subtitle}>
          Real-time simulation of racing dynamics using curvature-based speed control.
        </p>
      </section>

      {/* DEMO */}
      <section style={{ marginBottom: "60px" }}>
        <Circuit />
      </section>

      {/* OVERVIEW */}
      <section style={section}>
        <h2 style={sectionTitle}>Overview</h2>

        <p style={text}>
          This project simulates vehicle movement around a racing circuit using
          a custom path system. Instead of constant speed, the car dynamically
          adjusts its velocity depending on the curvature of the track.
        </p>
      </section>

      {/* TECH */}
      <section style={section}>
        <h2 style={sectionTitle}>Technical Approach</h2>

        <ul style={list}>
          <li>Path interpolation using segmented coordinates</li>
          <li>Curvature-based speed adjustment</li>
          <li>Real-time animation loop (requestAnimationFrame)</li>
          <li>Canvas rendering and motion trails</li>
        </ul>
      </section>

      {/* VALUE */}
      <section style={section}>
        <h2 style={sectionTitle}>What this demonstrates</h2>

        <ul style={list}>
          <li>System design and problem solving</li>
          <li>Mathematical reasoning applied to UI</li>
          <li>Performance-aware rendering</li>
          <li>Interactive visualization skills</li>
        </ul>
      </section>
    </main>
  );
}

/* 🎨 styles */

const container = {
  padding: "120px 60px",
  maxWidth: "1000px",
  margin: "0 auto",
  color: "white",
};

const title = {
  fontSize: "40px",
};

const subtitle = {
  opacity: 0.7,
  marginTop: "10px",
};

const section = {
  marginBottom: "50px",
};

const sectionTitle = {
  fontSize: "22px",
  marginBottom: "10px",
};

const text = {
  opacity: 0.7,
};

const list = {
  opacity: 0.7,
  paddingLeft: "20px",
};